pub fn max(versions: &[SemVer]) -> Option<&SemVer> {
    if versions.is_empty() {
        return None;
    }
    let mut max_v = &versions[0];
    for v in versions.iter().skip(1) {
        if v > max_v {
            max_v = v;
        }
    }
    Some(max_v)
}
